await story('A8-09-pending-matrix-mismatch-stop',async()=>{
 const primary=api;const n=await context(cases[0]);await signIn(n.p,'negative');await n.p.fill('#quickFleetLabel','Negative control fleet');await n.p.locator('[data-quick-pairing] form button[type=submit]').click();await n.p.locator('[data-quick-pairing] .hub-fp-groups').waitFor();const code=(await n.p.locator('[data-quick-pairing] .hub-fp-groups').first().innerText()).trim();
 const nh=join(scratch,'negative-member');mkdirSync(nh,{mode:0o700});const negativeApi=createHubMemberPairingApi({home:nh,enabled:()=>true,link:()=> 'offline',pollMs:250});extraPairings.push(negativeApi);fx.fm.attachHubMemberPairing(negativeApi);
 const nl=await context(cases[0]);const issued=await(await fetch(fx.base+'/auth/issue-code',{method:'POST',headers:{'X-Agend-Token':fx.fm.webToken}})).json();await nl.p.goto(fx.base+'/signin');await nl.p.fill('#code',issued.code);await nl.p.click('#go');await nl.p.waitForURL(fx.base+'/ui');await nl.p.goto(fx.base+'/settings/hub');await nl.p.fill('#hubAddress',memberOrigin);await nl.p.fill('#hubCode',code);await nl.p.locator('#hub-connect form button[type=submit]').click();await apply(nl.p,'.hub-local-confirm');await n.p.getByRole('button',{name:'They match',exact:true}).waitFor();
 for(const c of matrix('full')){const o=await context(c);await signIn(o.p,'negative');await o.p.getByRole('button',{name:c.lang==='en'?'They match':'指紋相符',exact:true}).waitFor();await shot(o.p,`A8-09-pending-${caseName(c)}`);await geometry(o.p,caseName(c)+' pending');await o.ctx.close();}
 peer.state.mode='missing';await n.p.reload();await n.p.locator('[data-welcome=unknown]').waitFor();await shot(n.p,'A8-09-pending-unknown');check('unknown does not create a local profile',negativeApi.view().state!=='paired');peer.state.mode='ok';await n.p.reload();await n.p.getByRole('button',{name:'They do not match',exact:true}).click();await n.p.getByText('Pairing stopped',{exact:true}).waitFor();check('mismatch cancels without credential',negativeApi.view().state!=='paired');await shot(n.p,'A8-09-mismatch-stopped');
 negativeApi.cancel();fx.fm.attachHubMemberPairing(primary);await nl.ctx.close();await n.ctx.close();
 const z=await context(cases[1]);await signIn(z.p,'expiry');await z.p.fill('#quickFleetLabel','Stop control');await z.p.locator('[data-quick-pairing] form button[type=submit]').click();await z.p.locator('[data-quick-pairing] .hub-fp-groups').waitFor();await z.p.getByRole('button',{name:'停止配對',exact:true}).click();await z.p.getByText('已停止配對',{exact:true}).waitFor();await shot(z.p,'A8-09-phone-stop');await z.ctx.close();
});
